@spec generators_spec  src=tests/specs/generators_spec.lua  loc=850  cases=60
@exercises generators (generators)
@surface   generators.glyphOf, generators.labelOf, generators.fieldsFor, generators.parksNotes, generators.parkWindows, generators.continuousTargets, generators.chainDestType, generators.destOf, generators.retarget, generators.fieldRange, generators.waveBody, generators.customise, generators.seed, generators.thinCurve

# Intent
  generators.lua: slide glide-in envelope.

# Helpers
  @fn expand(kind, hostRec, params, ctx)  @ 8-10
      -- Kinds run alone here, so the chain state equals the original: stream == host (the chain head).
  @fn slideCtx(nextNote, pbRangeCents)  @ 13-16
      -- A slide host (pitch 60) and a ctx supplying the next same-lane note + pb ceiling.
  @fn slideHost(detune)  @ 17-19
  @fn triangle()  @ 23-29
      -- A loop-closed triangle in the normalized domain (-1 .. +1 .. -1), one QN long.
  @fn pts(rows)  @ 33-39
      -- Curve points positionally: {ppq, val, shape?, tension?}; shape defaults to linear, the one kind
      -- thinCurve is allowed to drop.

# Cases
  @case 'every registered kind carries a glyph, one codepoint, shared with no other kind'  [pure]  @ 46-55
  @case 'glyphOf resolves off the registry, and falls back for a kind the registry has lost'  [pure]  @ 59-63
  @case 'labelOf resolves off the registry, and keeps a lost kind\'s name in the mark'  [pure]  @ 67-72
  @case 'fieldsFor gives a lost kind no rows'  [pure]  @ 76-80
  @case 'slide glides in: flat hold, slur to the interval, then hand off to tm\'s close'  [pure]  @ 86-97
  @case 'slide interval includes detune (the microtonal offset rides in detune, not pitch)'  [pure]  @ 101-105
  @case 'slide clamps the target to ctx.pbRangeCents (a pb can only bend so far)'  [pure]  @ 109-113
  @case 'slide.target='fixed' is a fixed-cents bend (cents demand, no next-note lookup)'  [pure]  @ 117-122
  @case 'slide.target='next' with no following note yields no delta (carrier untouched)'  [pure]  @ 126-130
  @case 'slide to a unison next note yields no delta (zero interval)'  [pure]  @ 134-138
  @case 'trill tiles the window from its start, alternating host pitch with the cents demand'  [pure]  @ 144-157
  @case 'trill measures its demand from what the host sounds, detune and all'  [pure]  @ 161-169
  @case 'a trill\'s tiles each name a step of their own -- the host\'s, and the demand above it'  [pure]  @ 173-185
  @case 'a trill off a host with no intent derives none -- the field stays sparse'  [pure]  @ 189-196
  @case 'parksNotes is true for any note-dest kind, false for a continuous kind / husk'  [pure]  @ 202-207
  @case 'parkWindows emits an evType-tagged window per continuous/replace target (note discrete, cc, pb augment)'  [pure]  @ 211-226
  @case 'the ownership predicates ignore bypass: a bypassed chain still parks and still scopes its target'  [pure]  @ 230-240
  @case 'chainDestType demotes a bypassed replace stage to augment, and only that stage'  [pure]  @ 244-254
  @case 'destOf falls back to the registry dest; a dest param overrides it'  [pure]  @ 260-265
  @case 'fieldsFor prepends a Dest row only where the kind can serve more than one target'  [pure]  @ 269-277
  @case 'retarget between dests of equal reference leaves the magnitudes alone'  [pure]  @ 281-286
  @case 'retarget rescales magnitudes by proportion of the dest reference'  [pure]  @ 290-296
  @case 'fieldRange spans both ways for a signed magnitude, one way for an unsigned one'  [pure]  @ 300-306
  @case 'retarget carries a signed magnitude across with its sign intact'  [pure]  @ 310-316
  @case 'parkWindows follows the dest param, not the registry (a retargeted pb kind parks cc)'  [pure]  @ 320-327
  @case 'a sine-wave lfo on a cc dest tiles the window with extrema in cc steps, 0 at both ends'  [pure]  @ 333-347
  @case 'velPattern cycles its percent pattern per distinct onset; a chord shares one step'  [pure]  @ 353-368
  @case 'velPattern walks onset order regardless of input order, clamping vel to 1..127'  [pure]  @ 372-382
  @case 'ostinato tracks the sounding pitch across the region, not just the first note'  [pure]  @ 388-400
  @case 'ostinato rests when no region note sounds at the gate onset'  [pure]  @ 404-413
  @case 'ostinato emits one gated note per sounding voice (a chord -> multiple lanes)'  [pure]  @ 417-428
  @case 'chord-stamp rebases the pattern chord onto each member; lane-1 note lands on the trigger'  [pure]  @ 434-451
  @case 'chord-stamp moves every voice by the cents from its root to the trigger'  [pure]  @ 455-475
  @case 'chord-stamp fires a chord on every region member (all lanes are triggers)'  [pure]  @ 479-495
  @case 'chord-stamp with no lane-1 note in the pattern is inert (no root to rebase from)'  [pure]  @ 499-509
  @case 'chord-stamp voices name the trigger\'s step plus their own interval from the root'  [pure]  @ 513-528
  @case 'the kinds that copy a pitch copy the intent standing beside it'  [pure]  @ 534-546
  @case 'lfo tiles the curve at 1/period QN, mapping each val by offset + scale, edges seeded'  [pure]  @ 552-569
  @case 'lfo maps norm in whatever units the dest counts in -- cents on pb'  [pure]  @ 573-582
  @case 'lfo does not clamp -- the body holds no dest knowledge, and the cc seat clamps'  [pure]  @ 586-595
  @case 'lfo with an empty or lengthless curve is inert (no delta)'  [pure]  @ 599-608
  @case 'every wave draws a loop-closed normalized body, and all but square open at rest'  [pure]  @ 614-628
  @case 'the sine wave is four slow-bridged extrema; the triangle is the same points ridden linearly'  [pure]  @ 632-645
  @case 'a saw resets mid-body, so its cycle starts and ends at rest'  [pure]  @ 649-661
  @case 'a wave body is four beats of the take that asked for it, never a fixed tick count'  [pure]  @ 665-673
  @case 'a cycle squeezed below the tick still emits its breakpoints a tick apart'  [pure]  @ 677-690
  @case 'a named wave is what the lfo expands -- a stored body is dormant until custom'  [pure]  @ 694-706
  @case 'onset ramps the whole displacement in from rest over its QN, offset included'  [pure]  @ 710-722
  @case 'customise stamps the wave onto the body and flips the stage to custom'  [pure]  @ 726-739
  @case 'custom is an arrival: the wave ladder steps over it, and its own pick re-seeds'  [pure]  @ 743-755
  @case 'thinCurve returns a degenerate curve verbatim -- endpoints are never candidates'  [pure]  @ 761-768
  @case 'thinCurve collapses a collinear linear run to its endpoints'  [pure]  @ 772-779
  @case 'thinCurve drops a spike whose vertical error only meets the tolerance'  [pure]  @ 783-787
  @case 'thinCurve keeps a spike whose vertical error exceeds the tolerance'  [pure]  @ 791-794
  @case 'thinCurve keeps a stepped run whole, collinear though its points are'  [pure]  @ 798-802
  @case 'thinCurve rides a curved point through with its tension intact'  [pure]  @ 806-812
  @case 'thinCurve lets a non-linear point pin its successor as well as itself'  [pure]  @ 816-821
  @case 'thinCurve treats a missing shape as non-linear -- under-thin over silently ramping'  [pure]  @ 825-829
  @case 'thinCurve keeps a stack of coincident points -- a zero-width span has no chord'  [pure]  @ 833-837
  @case 'thinCurve gives a dual-point pair no special protection'  [pure]  @ 841-847

